static uint16_t s_charge;               // Infernal Scepter: frames charged (fire held)
static uint16_t s_chan;                 // Eldritch Focus: frames channelled
static bool     s_held;                 // fire was held last tick
static uint16_t s_static;               // Stormcaller Static Charge: hits since the last burst
static uint16_t s_amStack, s_amT;       // Raycaster Arcane Mastery: stacks, frames until reset
static uint16_t s_heal;                 // damage banked toward Covenant / Blood Pact healing
static uint16_t s_bpCd;                 // Blood Pact cooldown
static uint16_t s_sumT;                 // Necromancer ordinary-summon timer
static uint16_t s_ultKind;              // class whose ultimate is running
static int16_t  s_rewardProp = -1;      // the mini-boss / Dragon reward chest (one prop, reused)

#define CLASS_ON(c)     (rc_class == (c))


//*****************************************************************************
// Damage the player deals. Every attack, beam tick, burn and summon hit goes
// through PlayerHit so all bonuses, crits and on-hit effects apply the same way.
//*****************************************************************************
static void KillEnemy(Enemy *e);

void rc_IgniteEnemy(Enemy *e, uint16_t stacks)
{
    uint32_t t = (120UL * (100u + (uint16_t)rc_fx[FX_BURNDUR])) / 100u;     // 4 s, Cinder Crown longer

    if(e->type == ET_DRAGON) t >>= 1;                                       // strong fire resistance
    e->burnStk = (uint16_t)((e->burnStk + stacks > 5u) ? 5u : e->burnStk + stacks);
    e->burn    = (uint16_t)t;                                               // a new hit refreshes the burn
}


void rc_DamageEnemyEx(Enemy *e, uint16_t dmg, int16_t c, int16_t s, bool quiet)
{
    (void)c; (void)s;
    if(e->sum == SUM_ALLY) return;
    if(rc_Untargetable(e)) return;                                          // phasing ghost, split Slime King
    if(e->type == ET_HOBGOB && e->st != 3 && dmg > 1u) dmg--;               // shield (down while recovering)
    e->hp   -= (int16_t)dmg;
    e->flash = 3;
    rc_hud  |= HUD_LEFT;
    if(e->hp <= 0) { KillEnemy(e); return; }
    if(!quiet) rc_SfxSoft(&sfx_blip);
}


static uint16_t Wealth(void)            // Midas's Fortune steps: 100 / 250 / 500 gold
{
    return (uint16_t)((rc_gold >= 100u) + (rc_gold >= 250u) + (rc_gold >= 500u));
}


void rc_PlayerHit(Enemy *e, uint16_t base, uint16_t elem, uint16_t flags)
{
    int32_t  pct = 100 + rc_fx[FX_DMG];
    uint32_t d;
    uint16_t crit;

    if(!e->alive || e->sum == SUM_ALLY) return;

    switch(elem)                                                            // element gear
    {
        case EL_FIRE:     pct += rc_fx[FX_FIRE];  break;
        case EL_LIGHT:    pct += rc_fx[FX_LIGHT]; break;
        case EL_ARCANE:   pct += rc_fx[FX_BEAM];  break;
        case EL_ELDRITCH: pct += rc_fx[FX_WBEAM]; break;
        case EL_GOLD:     pct += (int32_t)rc_fx[FX_GILDDMG] * (rc_gold / 100u); break;
        default: break;
    }
    if(CLASS_ON(CL_PYRO) && e->burnStk) pct += 25;                          // Kindling
    if(CLASS_ON(CL_MIDAS)) pct += 10 * Wealth();                            // Midas's Fortune
    if(rc_HasRune(RU_GARSENAL)) pct += (rc_gold / 20u > 50u) ? 50 : rc_gold / 20u;
    if(rc_HasRune(RU_VOID))  pct += (int32_t)(e->mhp - e->hp) * 50 / (e->mhp ? e->mhp : 1);
    if(rc_HasRune(RU_REACH)) pct += (int32_t)(rc_ManaMax() - rc_mana) * 50 / rc_ManaMax();
    if(rc_relicMask & (1u << (I_BLOODHEART - I_FIRST_RELIC)))
        pct += (int32_t)(rc_maxHp - rc_hp) * 50 / rc_maxHp;
    if(CLASS_ON(CL_STORM) && elem == EL_LIGHT && s_static >= 5u)            // Static Charge burst
    {
        pct += rc_HasRune(RU_STATIC) ? 150 : 100;
        s_static = 0;
    }
    if(rc_ultT && s_ultKind == CL_RAY)   pct += 100 + rc_fx[FX_FRACT];      // Reality Fracture beams
    if(rc_ultT && s_ultKind == CL_MIDAS) pct += 50;                         // golden statues crack

    d = ((uint32_t)base * (uint32_t)pct + 50u) / 100u;
    if(elem == EL_FIRE && e->type == ET_DRAGON) d >>= 1;                    // Dragon: fire resistant
    crit = (uint16_t)(RC_CRIT_BASE_PCT + rc_fx[FX_CRIT] + ((elem == EL_ARCANE) ? rc_fx[FX_BCRIT] : 0));
    if(RAND(100) < crit) { d = (d * 3u + 1u) >> 1; rc_AddSpark(e->x, e->y, 8, 6, PT_PUFF_ARCANE, 5); }
    if(d < 1u) d = 1u;

    if(!(flags & HF_DOT))                                                   // on-hit effects
    {
        if(elem == EL_FIRE || RAND(100) < (uint16_t)rc_fx[FX_IGNITE]) rc_IgniteEnemy(e, 1);
        if(elem == EL_LIGHT && RAND(100) < (uint16_t)rc_fx[FX_STUN])
            e->freeze = RC_IS_BOSS(e->type) ? 10u : 20u;
        if(RAND(100) < (uint16_t)rc_fx[FX_GOLDPROC]) rc_GainGold(2);
        if((rc_relicMask & (1u << (I_PRIMAL - I_FIRST_RELIC))) && RAND(10) == 0u)
        {
            uint16_t k = RAND(3);                                           // Primal Core
            if(k == 0u)      rc_IgniteEnemy(e, 2);
            else if(k == 1u) e->freeze = 30;
            else             d += 3u;
        }
        if(CLASS_ON(CL_RAY) && elem == EL_ARCANE) { if(s_amStack < 10u) s_amStack++; s_amT = 90; }
        if(CLASS_ON(CL_STORM) && elem == EL_LIGHT) s_static++;
    }

    // Vampiric Covenant (Necromancer) / Blood Pact lifesteal (Warlock)
    if(CLASS_ON(CL_NECRO) || CLASS_ON(CL_WARLOCK))
    {
        uint16_t need = CLASS_ON(CL_NECRO) ? 25u : 30u;
        int16_t  bonus = CLASS_ON(CL_NECRO) ? rc_fx[FX_COVEN] : rc_fx[FX_LSTEAL];

        s_heal = (uint16_t)(s_heal + (d * (uint32_t)(100 + bonus)) / 100u);
        while(s_heal >= need) { s_heal -= need; rc_HealPlayer(1); }
    }
    if(rc_class && !rc_ultT && rc_ult < ULT_FULL)                           // the ultimate charges from damage
    {
        uint32_t u = rc_ult + (d * (uint32_t)(100 + rc_fx[FX_ULT])) / 100u;
        rc_ult = (u > ULT_FULL) ? ULT_FULL : (uint16_t)u;
        rc_hud |= HUD_ULT;
    }

    rc_DamageEnemyEx(e, (d > 999u) ? 999u : (uint16_t)d, 0, 0, (flags & HF_QUIET) != 0u);
}


//*****************************************************************************
// Allies: Necromancer summons, risen enemies, the Army of the Damned, Slime Crown
// slimes. They share the 16 enemy slots and never take one a wave needs.
//*****************************************************************************
uint16_t rc_CountAllies(uint16_t kind)
{
    uint16_t i, n = 0;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
        if(rc_en[i].alive && rc_en[i].sum == SUM_ALLY && (kind == 0xFFFFu || rc_en[i].st == kind)) n++;
    return n;
}


Enemy *rc_SpawnAlly(uint16_t type, int32_t x, int32_t y, uint16_t life, uint16_t kind)
{
    Enemy *a;

    if(rc_alive >= RC_MAX_ENEMIES - 3u) return NULL;            // keep room for the wave
    if(Blocked(x, y, 230)) { x = rc_px; y = rc_py; }
    a = rc_SpawnEnemy(type, x, y);
    if(a == NULL) return NULL;
    a->sum  = SUM_ALLY;
    a->st   = kind;
    a->hp   = a->mhp = (int16_t)(((int32_t)(rc_kEnemy[type].hp + 6) * (100 + rc_fx[FX_SUMHP])) / 100);
    a->life = (uint16_t)(((uint32_t)life * (uint32_t)(100 + rc_fx[FX_SUMDUR])) / 100u);
    rc_AddSpark(a->x, a->y, 6, 10, PT_ORB_GREEN, 10);
    return a;
}


//*****************************************************************************
// Kills and rewards
//*****************************************************************************
static void BossChest(uint16_t sub, uint16_t arg, int32_t x, int32_t y)
{
    if(s_rewardProp < 0 || !rc_prop[s_rewardProp].used)
    {
        int16_t p = rc_AddProp(PR_CHEST, sub, x, y);           // a new prop if the last chest is unopened
        if(p < 0) { rc_GainGold(80); return; }
        s_rewardProp = p;
    }
    {
        Prop *p = &rc_prop[s_rewardProp];
        p->x = x; p->y = y; p->kind = PR_CHEST; p->sub = sub; p->arg = arg;
        p->used = 0; p->alive = 1; p->room = rc_RoomAt(x, y);
    }
}


static void KillEnemy(Enemy *e)
{
    const EnemyDef *d = &rc_kEnemy[e->type];
    uint16_t i;
    bool     boss = RC_IS_BOSS(e->type), burning = (e->burnStk != 0u);
    int32_t  ex = e->x, ey = e->y;

    e->alive = 0;
    if(rc_alive) rc_alive--;
    if(e->sum == SUM_ALLY) return;                              // an ally crumbled: no reward

    rc_GainGold(e->sum ? 1u : (uint16_t)d->gold);
    rc_GainXp(e->sum ? 1u : (uint16_t)d->xp);
    rc_kills++;
    rc_hud |= HUD_LEFT;
    rc_Sfx(&sfx_explosion);

    if(rc_HasRune(RU_LEECH) && ++rc_leechCnt >= 5u) { rc_leechCnt = 0; rc_HealPlayer(1); }
    if(rc_HasRune(RU_MOMENTUM)) rc_momentum = 90;
    if(burning && rc_HasRune(RU_ASHEN)) { rc_mana = (uint16_t)(rc_mana + 5u); if(rc_mana > rc_ManaMax()) rc_mana = rc_ManaMax(); }
    if(burning && rc_HasRune(RU_CINDERWAKE))
    {
        Obj *o = rc_NewObj(OB_AREA);
        if(o) { o->x = ex; o->y = ey; o->r = 600; o->life = 90; o->aux = AR_PFIRE; }
    }
    if(rc_HasRune(RU_SIPHON) && RAND(100) < 15u) rc_HealPlayer(1);
    if(rc_HasRune(RU_GTOUCH) && RAND(4) == 0u)   rc_GainGold(5);

    if(!e->sum && !boss)
    {
        if(rc_hp < rc_maxHp && RAND(100) < HEART_DROP_PCT) rc_DropHeart(ex, ey);
        else if(RAND(100) < MANA_DROP_PCT)
        {
            Obj *o = rc_NewObj(OB_MANA);
            if(o) { o->x = ex; o->y = ey; o->pal = PT_FLASK_MANA; o->life = MANA_BOTTLE_LIFE; }
        }
        // Necromancer: a slain enemy may rise as an ally (10%, max 2 risen)
        if(CLASS_ON(CL_NECRO) && e->type != ET_MIMIC && rc_CountAllies(AK_RISEN) < 2u &&
           RAND(100) < (uint16_t)(10 + rc_fx[FX_REZ]))
            (void)rc_SpawnAlly(e->type, ex, ey, 900, AK_RISEN);
        if((rc_relicMask & (1u << (I_SLIMECROWN - I_FIRST_RELIC))) && RAND(10) == 0u)
            (void)rc_SpawnAlly(ET_SLIME_S, ex, ey, 600, AK_SLIME);
    }

    if(e->type == ET_SLIME)                                     // splits into two small slimes
        for(i = 0; i < 2; i++)
        {
            Enemy *s2 = rc_SpawnEnemy(ET_SLIME_S, ex + (i ? 330L : -330L), ey);
            if(s2 != NULL && Blocked(s2->x, s2->y, 230)) { s2->x = ex; s2->y = ey; }
        }
    else if(e->type == ET_BOMBER)
        rc_Explode(ex, ey);
    else if(e->type == ET_MIMIC && rc_treasureOpen == 2u)
        rc_treasureOpen = 0;

    if(RC_IS_MINI(e->type))
    {
        uint16_t relic;                                         // signature relic per mini-boss
        switch(e->type)
        {
            case ET_EYEKING:   relic = I_EYE;        break;
            case ET_SLIMEKING: relic = I_SLIMECROWN; break;
            case ET_LICH:      relic = I_PHYLACTERY; break;
            case ET_GOLEM:     relic = I_PRIMAL;     break;
            default:           relic = I_BLOODHEART; break;    // Vampire Lord
        }
        rc_DropHeart(ex, ey);
        if(rc_miniAlive) rc_miniAlive--;
        rc_miniKills++;
        BossChest(CH_BOSS, relic, ex, ey);
        rc_Toast(rc_kEnemyName[e->type], " defeated!");
        rc_OnBossDeath(e, ex, ey);                              // Lich Lord's blast, Golem's walls ...
        for(i = 0; i < RC_MAX_ENEMIES; i++)                     // its summons vanish with it
            if(rc_en[i].alive && rc_en[i].sum == SUM_MINION)
            {
                rc_en[i].alive = 0;
                if(rc_alive) rc_alive--;
            }
    }

    if(e->type == ET_DRAGON)
    {
        rc_dragonAlive = 0;
        rc_dragonKills++;
        rc_GainGold(150);
        rc_DropHeart(ex, ey);
        BossChest(CH_DRAGON, 0, ex, ey);
        rc_Toast("The Dragon falls!", NULL);
        for(i = 0; i < rc_nProp; i++)                           // every chest refreshes (rc.md 15.4)
            if(rc_prop[i].kind == PR_CHEST && (int16_t)i != rc_treasureProp && (int16_t)i != s_rewardProp)
            {
                rc_prop[i].used  = 0;
                rc_prop[i].alive = 1;
                if(rc_prop[i].sub != CH_GOOD) rc_prop[i].sub = RAND(3);
            }
    }

    if(boss) rc_RefreshTheme();
}


//*****************************************************************************
// Staffs: hitscan beams, with pierce, chain jumps (Thunderbolt, Gilded coins)
// and the Raycaster rune effects.
//*****************************************************************************
uint16_t rc_StaffMana(void)
{
    const StaffDef *sd = &rc_kStaffs[rc_eq[SL_WPN]];
    int32_t pct = 100 - rc_fx[FX_COST];

    if(sd->elem == EL_ARCANE) pct -= rc_fx[FX_BCOST] + (CLASS_ON(CL_RAY) ? 5 * s_amStack : 0);   // Arcane Mastery
    if(rc_ultT && s_ultKind == CL_RAY) return 0;                // Reality Fracture beams are free
    if(pct < 25) pct = 25;
    return (uint16_t)(((uint32_t)sd->mana * (uint32_t)pct + 99u) / 100u);
}


// The nearest hostile within `range` of (x, y) that is not in hitMask.
static int16_t Nearest(int32_t x, int32_t y, int16_t range, uint16_t hitMask)
{
    uint16_t i;
    int16_t  best = -1, bd = range, d;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        const Enemy *e = &rc_en[i];

        if(!e->alive || e->sum == SUM_ALLY || (hitMask & (1u << i))) continue;
        if(rc_Untargetable(e)) continue;
        d = DistP(x, y, e->x, e->y);
        if(d < bd) { bd = d; best = (int16_t)i; }
    }
    return best;
}


// One beam. Returns the bitmask of enemies it hit.
static uint16_t FireBeam(int16_t angle, uint16_t dmg, uint16_t elem, uint16_t pierce, uint16_t chain)
{
    uint16_t tile, side, hitMask = 0, left = (uint16_t)(1u + pierce), i;
    int16_t  c, s, best = -1, last = -1, rx, ry;
    int32_t  wall, bestAlong, along, perp;

    angle &= RC_ANGLE_MASK;
    wall = (int32_t)rc_RC_CastRay(angle, &tile, &side) << 2;
    c = COS(angle);
    s = SIN(angle);

    while(left--)
    {
        best = -1;
        bestAlong = wall;
        for(i = 0; i < RC_MAX_ENEMIES; i++)
        {
            const Enemy *e = &rc_en[i];

            if(!e->alive || e->sum == SUM_ALLY || (hitMask & (1u << i))) continue;
            if(rc_Untargetable(e)) continue;
            rx = RD(e->x - rc_px);
            ry = RD(e->y - rc_py);
            along = ((int32_t)rx * c + (int32_t)ry * s) >> 14;
            if(along <= 0 || along >= bestAlong) continue;
            perp = ((int32_t)ry * c - (int32_t)rx * s) >> 14;
            if(perp < 0) perp = -perp;
            if(perp > rc_kEnemy[e->type].radius) continue;
            best = (int16_t)i;
            bestAlong = along;
        }
        if(best < 0) break;
        hitMask |= (uint16_t)(1u << best);
        last = best;
        if(rc_en[best].type == ET_HOBGOB && rc_en[best].st != 3u) left = 0;    // the shield stops the beam
        rc_PlayerHit(&rc_en[best], dmg, elem, 0);
    }

    // Astral Ricochet: a beam that missed seeks the nearest enemy in front.
    if(last < 0 && rc_HasRune(RU_RICOCHET))
    {
        int32_t ax = rc_px + (((int32_t)c * 3000L) >> 14), ay = rc_py + (((int32_t)s * 3000L) >> 14);
        last = Nearest(ax, ay, 2600, 0);
        if(last >= 0) { hitMask |= (uint16_t)(1u << last); rc_PlayerHit(&rc_en[last], dmg, elem, 0); }
    }
    // Prismatic Afterimage: 25% chance for a weaker extra jump.
    if(last >= 0 && rc_HasRune(RU_AFTERIMAGE) && RAND(4) == 0u) chain++;

    // Chain jumps (lightning, ricocheting coins): 75% damage each, within 3 tiles.
    while(chain-- && last >= 0)
    {
        int16_t n = Nearest(rc_en[last].x, rc_en[last].y, 3072, hitMask);

        if(n < 0) break;
        rc_AddSpark(rc_en[n].x, rc_en[n].y, 6, 6, (elem == EL_GOLD) ? PT_ORB_BOLT : PT_PUFF_ARCANE, 6);
        hitMask |= (uint16_t)(1u << n);
        rc_PlayerHit(&rc_en[n], (uint16_t)((dmg * 3u + 3u) >> 2), elem, 0);
        last = n;
    }
    return hitMask;
}


static uint16_t StaffCooldown(const StaffDef *sd)
{
    int32_t a = rc_fx[FX_ASPD] + ((sd->elem == EL_LIGHT) ? rc_fx[FX_LSPD] : 0);
    uint32_t cd;

    if(a > 60) a = 60;
    cd = ((uint32_t)sd->cooldown * (uint32_t)(100 - a)) / 100u;
    if(rc_haste) cd >>= 1;
    return (cd < 3u) ? 3u : (uint16_t)cd;
}


// Pay for one attack: mana, or gold for the Gilded Scepter (mana when out of gold).
static bool PayAttack(const StaffDef *sd)
{
    uint16_t cost = rc_StaffMana();

    if(sd->elem == EL_GOLD && rc_gold > 0u) { rc_gold--; rc_hud |= HUD_GOLD; return true; }
    if(rc_nullify) cost = (uint16_t)(cost * 2u);
    if(rc_mana < cost)
    {
        rc_cdStaff = rc_cdStaffMax = 10;                        // retry delay, so holding fire won't spam
        rc_manaFlash = 12;
        rc_Sfx(&sfx_menu_bump);
        return false;
    }
    rc_mana -= cost;
    return true;
}


static void Attack(uint16_t mult)       // mult in quarters: 4 = normal, up to 16 for a full charge
{
    const StaffDef *sd = &rc_kStaffs[rc_eq[SL_WPN]];
    uint16_t beams = sd->beams, spread = sd->spread, i, dmg;
    uint16_t pierce = sd->pierce, chain = (uint16_t)(sd->chain ? sd->chain + rc_fx[FX_CHAIN] : 0u);
    int16_t  off;

    if(!PayAttack(sd)) return;
    if(sd->chain && rc_HasRune(RU_ARC) && RAND(10) < 3u) chain++;       // Arc Conduit
    if(rc_HasRune(RU_TWIN)) beams = (uint16_t)(beams + 2u);             // Twin Spectrum
    if(rc_HasRune(RU_PIERCE) && pierce < 99u) pierce++;                 // Piercing Light
    if(rc_HasRune(RU_ECHOES) && RAND(5) == 0u) beams++;                 // Echoes
    if(beams > 5u) beams = 5u;
    if(beams > 1u && spread == 0u) spread = 10u;
    dmg = (uint16_t)((sd->dmg * mult + 2u) >> 2);

    rc_cdStaff = rc_cdStaffMax = StaffCooldown(sd);
    rc_fxN     = beams;
    rc_fxColor = sd->color;
    for(i = 0; i < beams; i++)
    {
        off = (int16_t)((((int16_t)(2 * i) - (int16_t)(beams - 1)) * (int16_t)spread) / 2);
        (void)FireBeam((int16_t)(rc_ang + off), dmg, sd->elem, pierce, chain);
        rc_fxX[i] = (int16_t)(RC_VIEW_X0 + RC_VIEW_W / 2 + off * RC_PX_PER_UNIT);
    }
    rc_fxTimer   = 4;
    rc_viewDirty = 2;
    if(rc_sfxHold == 0) Buzzer_PlaySfx(sd->sfx);
    rc_stepBlock = 5;
}


//*****************************************************************************
// Consumables (rc.md 10): no mana, each has its own cooldown.
//*****************************************************************************
static bool ThrowFlask(uint16_t kind)
{
    int16_t c = COS(rc_ang), s = SIN(rc_ang);
    int32_t sx = rc_px + (((int32_t)c * 300L) >> 14), sy = rc_py + (((int32_t)s * 300L) >> 14);
    Obj    *o = rc_NewObj(OB_FLASK);

    if(o == NULL) return false;
    if(Blocked(sx, sy, 60)) { sx = rc_px; sy = rc_py; }
    o->x = sx;  o->y = sy;
    o->vx = (int16_t)(((int32_t)c * 110L) >> 14);
    o->vy = (int16_t)(((int32_t)s * 110L) >> 14);
    o->z = 9;  o->aux = kind;  o->life = 42;
    o->pal = PT_FLASK_FIRE + kind;
    Buzzer_PlaySfx(&sfx_jump);
    return true;
}


// A flask bursts: fire ignites (full stacks), frost freezes (half on bosses), venom lingers.
void rc_Shatter(Obj *o)
{
    uint16_t kind = o->aux, i;
    int16_t  rad  = rc_kPotRadius[kind];

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        Enemy *e = &rc_en[i];

        if(!e->alive || e->sum == SUM_ALLY) continue;
        if(DistP(e->x, e->y, o->x, o->y) >= rad + (rc_kEnemy[e->type].radius >> 1)) continue;
        rc_PlayerHit(e, rc_kPotDmg[kind], (kind == PK_FIRE) ? EL_FIRE : EL_ARCANE, HF_QUIET);
        if(!e->alive) continue;
        if(kind == PK_FIRE)       rc_IgniteEnemy(e, 5);
        else if(kind == PK_FROST) { e->freeze = RC_IS_BOSS(e->type) ? 40u : 80u; e->slow = 220; }
        else                      e->slow = 60;
    }
    o->kind = OB_CLOUD;
    o->age  = 0;
    o->life = rc_kPotLife[kind];
    o->sc   = rc_kPotScale[kind];
    o->pal  = PT_PUFF_FIRE + kind;
    o->z    = 0;
    o->vx   = o->vy = 0;
    rc_Sfx(&sfx_explosion);
}


static bool UseConsumable(uint16_t it)
{
    switch(it)
    {
        case I_FIRE:  return ThrowFlask(PK_FIRE);
        case I_FROST: return ThrowFlask(PK_FROST);
        case I_VENOM: return ThrowFlask(PK_VENOM);
        case I_ELIXIR:
            if(rc_hp >= rc_maxHp) return false;
            rc_HealPlayer(rc_maxHp);
            return true;
        case I_HASTE: rc_haste = 300; rc_hud |= HUD_HINT; return true;
        case I_AEGIS:
            if(rc_aegis) return false;
            rc_aegis = 1; rc_hud |= HUD_HINT; return true;
        case I_TOME:                                            // three homing bolts at the nearest foes
        {
            uint16_t k, mask = 0;
            for(k = 0; k < 3u; k++)
            {
                int16_t n = Nearest(rc_px, rc_py, 9000, mask);
                if(n < 0) break;
                mask |= (uint16_t)(1u << n);
                rc_AddSpark(rc_en[n].x, rc_en[n].y, 6, 8, PT_PUFF_ARCANE, 8);
                rc_PlayerHit(&rc_en[n], 4, EL_ARCANE, 0);
            }
            return mask != 0u;
        }
        case I_WARP:                                            // up to 3 tiles, never into a wall
        {
            int16_t c = COS(rc_ang), s = SIN(rc_ang), k;
            for(k = 0; k < 24; k++)
            {
                int32_t nx = rc_px + (((int32_t)c * 128L) >> 14), ny = rc_py + (((int32_t)s * 128L) >> 14);
                if(Blocked(nx, ny, RC_PLAYER_R)) break;
                rc_px = nx; rc_py = ny;
            }
            if(rc_invuln < 20u) rc_invuln = 20;
            rc_viewDirty = 2;
            return true;
        }
        default:                                                // I_MANAPOT
            if(rc_mana >= rc_ManaMax()) return false;
            rc_mana = (uint16_t)(rc_mana + MANA_BOTTLE);
            if(rc_mana > rc_ManaMax()) rc_mana = rc_ManaMax();
            return true;
    }
}


//*****************************************************************************
// Fire input (D-pad Down). Normal staffs fire while held; the Infernal Scepter
// charges while held and fires on release; the Eldritch Focus channels.
//*****************************************************************************
void rc_FireInput(bool held)
{
    uint16_t it = rc_SelItem();
    bool     pressed = held && !s_held, released = !held && s_held;

    s_held = held;
    if(rc_cdStaff) rc_cdStaff--;
    if(rc_silence) { if(pressed) { rc_Sfx(&sfx_menu_bump); rc_hud |= HUD_HINT; } s_charge = s_chan = 0; return; }

    if(it >= I_FIRST_CONS)                                      // a consumable is selected
    {
        uint16_t k = (uint16_t)(it - I_FIRST_CONS);

        if(!pressed || it >= I_FIRST_GEAR) return;
        if(rc_cdCons[k] || !UseConsumable(it)) { rc_Sfx(&sfx_menu_bump); return; }
        rc_cdCons[k] = (uint16_t)(((uint32_t)rc_kItems[it].val * 10u * (uint32_t)(100 - ((rc_fx[FX_ASPD] > 60) ? 60 : rc_fx[FX_ASPD]))) / 100u);
        rc_SpendSelected();
        rc_Sfx(&sfx_powerup);
        return;
    }

    switch(rc_kStaffs[it].mode)
    {
        case SM_CHARGE:
            if(held) { if(s_charge < 45u) s_charge++; rc_fxColor = COLOR_ORANGE; rc_viewDirty = 2; }
            else if(released && s_charge) { if(!rc_cdStaff) Attack((uint16_t)(4u + s_charge / 4u)); s_charge = 0; }
            break;
        case SM_CHANNEL:
            if(!held) { s_chan = 0; break; }
            if(rc_cdStaff) break;
            s_chan = (uint16_t)((s_chan < 120u) ? s_chan + rc_kStaffs[it].cooldown : 120u);
            Attack((uint16_t)(4u + s_chan / 8u));               // damage grows while channelled
            break;
        default:
            if(held && !rc_cdStaff) Attack(4);
            break;
    }
}


//*****************************************************************************
// Ultimates (rc.md 8.4): fire + stick button with a full meter.
//*****************************************************************************
void rc_TryUltimate(void)
{
    uint16_t i;

    if(!rc_class || rc_ultT || rc_ult < ULT_FULL) { rc_Sfx(&sfx_menu_bump); return; }
    rc_ult = 0;
    s_ultKind = rc_class;
    rc_hud |= HUD_ULT | HUD_HINT;
    rc_Sfx(&sfx_level_up);

    switch(rc_class)
    {
        case CL_PYRO:                                           // Supernova: burst + 10 s burning ground
            for(i = 0; i < RC_MAX_ENEMIES; i++)
                if(rc_en[i].alive && DistP(rc_en[i].x, rc_en[i].y, rc_px, rc_py) < 4096)
                {
                    rc_PlayerHit(&rc_en[i], 15, EL_FIRE, HF_QUIET);
                    if(rc_en[i].alive) rc_IgniteEnemy(&rc_en[i], 5);
                }
            {
                Obj *o = rc_NewObj(OB_AREA);
                if(o) { o->x = rc_px; o->y = rc_py; o->r = 3072; o->life = 300; o->aux = AR_PFIRE; }
            }
            rc_AddSpark(rc_px, rc_py, 4, 40, PT_PUFF_FIRE, 14);
            break;
        case CL_NECRO:                                          // Army of the Damned: 4 skeletons
            for(i = 0; i < 4u; i++)
            {
                Enemy *a = rc_SpawnAlly(ET_SKELETON, rc_px + ((i & 1u) ? 700L : -700L),
                                        rc_py + ((i & 2u) ? 700L : -700L),
                                        rc_HasRune(RU_LEGION) ? 450u : 300u, AK_ARMY);
                (void)a;
            }
            break;
        case CL_WARLOCK:                                        // Eldritch Singularity, 3 tiles ahead
        {
            Obj *o = rc_NewObj(OB_SING);
            if(o)
            {
                o->x = rc_px + (((int32_t)COS(rc_ang) * 3072L) >> 14);
                o->y = rc_py + (((int32_t)SIN(rc_ang) * 3072L) >> 14);
                o->r = (int16_t)((4096L * (100 + rc_fx[FX_SINGRAD])) / 100);
                o->life = 300;
            }
            break;
        }
        default:                                                // Storm, Raycaster, Midas: timed
            rc_ultT = (rc_class == CL_RAY) ? 150u : 300u;
            break;
    }
}


// Per tick: class passives and running ultimates.
void rc_ClassTick(void)
{
    uint16_t i;

    if(s_amT && --s_amT == 0u) s_amStack = 0;                  // Arcane Mastery fades after 3 s
    if(s_bpCd) s_bpCd--;

    // Blood Pact: below 20% mana, one heart becomes mana (never the last heart).
    if(CLASS_ON(CL_WARLOCK) && !s_bpCd && rc_mana * 5u < rc_ManaMax())
    {
        uint16_t cost = (uint16_t)((rc_fx[FX_CONVCOST] >= 1) ? 1u : 2u);
        if(rc_hp > cost + 2u)
        {
            rc_hp = (uint16_t)(rc_hp - cost);
            rc_mana = (uint16_t)(rc_mana + 25u + rc_fx[FX_CONV]);
            if(rc_mana > rc_ManaMax()) rc_mana = rc_ManaMax();
            s_bpCd = 90;
            rc_hud |= HUD_HEARTS;
        }
    }

    // Necromancer: an ordinary summon every 10 s, up to 2 (+ Phylactery Pendant).
    if(CLASS_ON(CL_NECRO) && ++s_sumT >= 300u)
    {
        s_sumT = 0;
        if(rc_CountAllies(AK_SUMMON) < (uint16_t)(2 + rc_fx[FX_SUMCNT]))
            (void)rc_SpawnAlly(ET_SKELETON, rc_px - (((int32_t)COS(rc_ang) * 700L) >> 14),
                               rc_py - (((int32_t)SIN(rc_ang) * 700L) >> 14), 600, AK_SUMMON);
    }

    if(!rc_ultT) return;
    rc_ultT--;
    if(s_ultKind == CL_STORM && (rc_ultT % 15u) == 0u)          // Eye of the Storm strikes
    {
        int16_t n = Nearest(rc_px, rc_py, 5120, 0);
        if(n >= 0)
        {
            rc_AddSpark(rc_en[n].x, rc_en[n].y, 10, 10, PT_ORB_BOLT, 6);
            rc_PlayerHit(&rc_en[n], 6, EL_LIGHT, HF_QUIET);
        }
    }
    if(s_ultKind == CL_RAY || s_ultKind == CL_MIDAS)            // Reality Fracture / Golden Cataclysm freeze
        for(i = 0; i < RC_MAX_ENEMIES; i++)
            if(rc_en[i].alive && rc_en[i].sum != SUM_ALLY && rc_en[i].freeze < 2u) rc_en[i].freeze = 2;
    if(!rc_ultT) rc_hud |= HUD_ULT | HUD_HINT;
    rc_viewDirty = 2;
}


bool rc_GoldStatues(void)               // Golden Cataclysm running (gold tint)
{
    return rc_ultT && s_ultKind == CL_MIDAS;
}


void rc_ResetCombat(void)
{
    s_charge = s_chan = 0;
    s_held = false;
    s_static = s_amStack = s_amT = s_heal = s_bpCd = s_sumT = 0;
    s_ultKind = CL_NONE;
    s_rewardProp = -1;
}


//*****************************************************************************
// Chests (rc.md 12): Mimics attack, cursed chests offer the Mimic Cloth, the
// rest let you pick 1 of 3. Boss chests first hand out their package.
//*****************************************************************************
static uint16_t RandomGeneral(void)  { return (uint16_t)(I_FIRST_GEAR + RAND(12)); }

static uint16_t RandomClassItem(void)
{
    uint16_t k, it;

    for(k = 0; k < 30u; k++)
    {
        it = (uint16_t)(I_CLASS0 + RAND(33));
        if(!rc_Owns(it)) return it;
    }
    return RandomGeneral();
}


void rc_OpenChest(uint16_t p)
{
    Prop *pr = &rc_prop[p];
    bool  treasure = ((int16_t)p == rc_treasureProp);

    if(pr->used) return;
    pr->used = 1;
    rc_AddSpark(pr->x, pr->y, 4, 14, PT_PUFF_ARCANE, 10);
    if(treasure) rc_treasureOpen = 0;
    rc_chestKind = pr->sub;
    rc_chestGold = (uint16_t)(((uint32_t)(20u + 2u * rc_wave) * (uint32_t)(100 + rc_fx[FX_CHESTGOLD])) / 100u);

    switch(pr->sub)
    {
        case CH_MIMIC:
        {
            Enemy *e = rc_SpawnEnemy(ET_MIMIC, pr->x, pr->y);
            if(e) { e->st = 1; e->tm = 12; }
            pr->alive = 0;
            if(treasure) rc_treasureOpen = 2;
            rc_Toast("It's a Mimic!", NULL);
            rc_Sfx(&sfx_hit);
            return;
        }
        case CH_CURSED:
            rc_EnterCards(CS_CURSED);
            return;
        case CH_BOSS:                                           // relic + general + class item, then pick 1 of 3
            rc_GiveBossPackage(pr->arg, RandomGeneral(), RandomClassItem());
            return;
        default:                                                // regular, good, Dragon: pick 1 of 3
            rc_EnterCards(CS_CHEST);
            return;
    }
}


uint16_t rc_RandomChestItem(bool classOnly)
{
    uint16_t k = classOnly ? 0u : RAND(10);

    if(k < 4u) return RandomClassItem();                        // 40% class gear
    if(k < 8u) return RandomGeneral();                          // 40% general gear
    k = (uint16_t)(I_PRISM + RAND(3));                          // 20% a generic staff (not one you own)
    return rc_Owns(k) ? RandomGeneral() : k;
}
